VALUES ('math1-set-001', 'math1', 'จำนวนและพีชคณิต', 'เซต', '[]', 'medium', 'ใช้สูตรยูเนียนของสองเซตจากข้อมูลสำรวจ', 'mc5', 'จากการสำรวจนักเรียน 50 คน พบว่าชอบดื่มชา 28 คน ชอบดื่มกาแฟ 22 คน และมี 10 คนที่ไม่ชอบดื่มทั้งสองอย่างเลย มีนักเรียนกี่คนที่ชอบดื่มทั้งชาและกาแฟ', '["6", "8", "10", "12", "14"]', '10', '["ชอบอย่างน้อย 1 อย่าง = 50-10 = 40 คน", "จาก |T∪C|=|T|+|C|-|T∩C| → 40=28+22-x → x=10"]', '["ลืมหักคนที่ไม่ชอบทั้งสองอย่างออกก่อนใช้สูตร"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('math1-log-001', 'math1', 'จำนวนและพีชคณิต', 'ตรรกศาสตร์', '[]', 'medium', 'หาข้อความสมมูลด้วย contrapositive', 'mc5', 'กำหนด p แทน ''ฝนตก'' และ q แทน ''ฉันพกร่ม'' ข้อความ ''ถ้าฝนไม่ตก แล้วฉันจะไม่พกร่ม'' สมมูลกับข้อความในข้อใด', '["ถ้าฝนตก แล้วฉันพกร่ม", "ถ้าฉันพกร่ม แล้วฝนตก", "ถ้าฉันไม่พกร่ม แล้วฝนไม่ตก", "ฝนตกและฉันพกร่ม", "ฝนไม่ตกหรือฉันไม่พกร่ม"]', 'ถ้าฉันพกร่ม แล้วฝนตก', '["ข้อความเดิมอยู่ในรูป ~p→~q", "สมมูลกับ contrapositive คือ q→p"]', '["สับสนระหว่างบทกลับ (converse) กับ contrapositive"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('math1-poly-001', 'math1', 'จำนวนและพีชคณิต', 'จำนวนจริงและพหุนาม', '[]', 'easy', 'ตั้งอสมการจากเงื่อนไขต้นทุน-กำไร', 'mc5', 'ร้านขายเสื้อได้กำไรตัวละ 150 บาท และมีค่าใช้จ่ายคงที่วันละ 3,000 บาท ร้านต้องขายเสื้ออย่างน้อยกี่ตัวต่อวันจึงจะไม่ขาดทุน', '["15", "18", "20", "22", "25"]', '20', '["ตั้งอสมการ 150x-3000≥0", "แก้ได้ x≥20"]', '["ลืมใส่เครื่องหมายเท่ากับ (ไม่ขาดทุน = กำไรอย่างน้อย 0)"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('math1-fn-001', 'math1', 'จำนวนและพีชคณิต', 'ฟังก์ชัน', '["แคลคูลัส"]', 'hard', 'แปลงเงื่อนไขจริงเป็นฟังก์ชันกำลังสองแล้วหาค่าสูงสุด', 'mc5', 'กำไรต่อวัน P(x) บาท ของร้านเบเกอรี่เมื่อขายเค้ก x ชิ้น เป็นฟังก์ชันพหุนามกำลังสอง โดยวันที่ไม่ขายเลยขาดทุน 100 บาท ส่วนวันที่ขาย 10 ชิ้น และ 30 ชิ้น มีกำไรเท่ากันคือ 200 บาท ร้านนี้จะมีกำไรสูงสุดต่อวันเท่าไร', '["250 บาท", "275 บาท", "300 บาท", "325 บาท", "350 บาท"]', '300 บาท', '["ตั้ง P(x)=ax²+bx+c จาก 3 เงื่อนไข", "แก้ระบบสมการได้ P(x)=-x²+40x-100", "จุดสูงสุดอยู่ที่ x=20 ได้ P(20)=300 บาท"]', '["ตั้งสมการจากเงื่อนไขผิดคู่ ทำให้แก้ระบบไม่ตรง"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('math1-explog-001', 'math1', 'จำนวนและพีชคณิต', 'เอกซ์โพเนนเชียลและลอการิทึม', '[]', 'medium', 'การเติบโตแบบทวีคูณ (exponential growth)', 'mc5', 'แบคทีเรียชนิดหนึ่งเพิ่มเป็น 2 เท่าทุก 3 ชั่วโมง เริ่มต้นมี 500 ตัว อีกกี่ชั่วโมงจึงจะมีครบ 4,000 ตัว', '["6", "9", "12", "15", "18"]', '9', '["4000/500=8=2³", "ต้องเพิ่มเป็น 2 เท่า 3 รอบ รอบละ 3 ชม.", "รวม 9 ชั่วโมง"]', '["คูณ 3 ชม. กับ 8 เท่าตรงๆ แทนที่จะแปลงเป็นเลขชี้กำลังก่อน"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
