VALUES ('math1-matrix-001', 'math1', 'จำนวนและพีชคณิต', 'เมทริกซ์', '[]', 'medium', 'แก้ระบบสมการเชิงเส้น 2 ตัวแปรจากสถานการณ์จริง', 'mc5', 'ร้านขายผลไม้ วันแรกขายส้ม 2 กก. และแอปเปิ้ล 3 กก. ได้เงินรวม 220 บาท วันที่สองขายส้ม 4 กก. และแอปเปิ้ล 1 กก. ได้เงินรวม 140 บาท ส้มราคากิโลกรัมละกี่บาท (แก้ระบบสมการด้วยเมทริกซ์)', '["15", "20", "25", "30", "35"]', '20', '["ตั้ง 2x+3y=220 และ 4x+y=140", "แก้ระบบสมการได้ x=20 (ส้ม), y=60 (แอปเปิ้ล)"]', '["สลับตัวแปร x,y ระหว่างส้มกับแอปเปิ้ล"]');
