VALUES ('math1-seq-001', 'math1', 'จำนวนและพีชคณิต', 'ลำดับและอนุกรม', '[]', 'medium', 'ผลบวกอนุกรมเลขคณิต', 'mc5', 'นายเอฝากเงินเดือนแรก 500 บาท และฝากเพิ่มเดือนละ 100 บาทจากเดือนก่อนหน้าไปเรื่อยๆ (ไม่มีดอกเบี้ย) ครบ 12 เดือน จะมีเงินฝากสะสมทั้งหมดกี่บาท', '["10,800", "11,700", "12,600", "13,200", "14,400"]', '12,600', '["เป็นลำดับเลขคณิต a₁=500, d=100, n=12", "Sn=n/2[2a₁+(n-1)d]=6[1000+1100]=12,600 บาท"]', '["ใช้สูตรผลบวกลำดับเรขาคณิตแทนเลขคณิต"]');
