VALUES ('math1-prob-dist-001', 'math1', 'สถิติและความน่าจะเป็น', 'การแจกแจงความน่าจะเป็นเบื้องต้น', '[]', 'hard', 'การแจกแจงทวินาม', 'mc5', 'โรงงานผลิตหลอดไฟ มีโอกาสเป็นหลอดเสีย 10% สุ่มหลอดไฟมา 3 หลอด ความน่าจะเป็นที่จะได้หลอดเสียพอดี 1 หลอด เท่ากับเท่าใด', '["0.081", "0.243", "0.27", "0.343", "0.729"]', '0.243', '["ใช้สูตรทวินาม C(3,1)(0.1)¹(0.9)²", "=3×0.1×0.81=0.243"]', '["ลืมคูณด้วย C(3,1)"]');
