VALUES ('math1-prob-001', 'math1', 'สถิติและความน่าจะเป็น', 'ความน่าจะเป็น', '[]', 'easy', 'ความน่าจะเป็นพื้นฐาน', 'mc5', 'กล่องใบหนึ่งมีลูกบอลสีแดง 4 ลูก และสีน้ำเงิน 6 ลูก สุ่มหยิบลูกบอล 1 ลูก ความน่าจะเป็นที่จะได้ลูกบอลสีแดงเท่ากับเท่าใด', '["1/5", "2/5", "1/2", "3/5", "4/5"]', '2/5', '["P(แดง)=4/10=2/5"]', '["ลืมลดเศษส่วนให้เป็นเศษส่วนอย่างต่ำ"]');
